#if APP_TESTS
using System;using System.IO;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace FileCompass {
    internal static class FieldBorderTests {
        internal static int Run(string root){Directory.CreateDirectory(root);var log=new System.Collections.Generic.List<string>();try{FluentTheme.Ensure();Verify(root,(ok,label)=>{if(!ok)throw new Exception(label);log.Add(label);});log.Add("PASS: "+log.Count+" checks");File.WriteAllLines(Path.Combine(root,"result.txt"),log);return 0;}catch(Exception ex){log.Add("FAIL: "+ex);File.WriteAllLines(Path.Combine(root,"result.txt"),log);return 1;}}
        internal static void Verify(string root,Action<bool,string> check){
            var panel=new StackPanel{Margin=new Thickness(12)};var text=new TextBox{Text="Segoe UI",Height=28,Margin=new Thickness(0,4,0,4)};var combo=new ComboBox{Height=28,Margin=new Thickness(0,4,0,4)};combo.Items.Add("Segoe UI");combo.Items.Add("Consolas");combo.SelectedIndex=0;var password=new PasswordBox{Password="fixture",Height=28,Margin=new Thickness(0,4,0,4)};panel.Children.Add(text);panel.Children.Add(combo);panel.Children.Add(password);
            var w=new Window{Width=360,Height=230,Content=panel,Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false,ShowInTaskbar=false};FluentTheme.Dialog(w);
            try{w.Show();NavigationTests.Wait(Task.Delay(160));w.UpdateLayout();
                foreach(double scale in new[]{1.0,1.25,1.5,2.0})foreach(Control field in new Control[]{text,combo,password}){
                    var frame=(Border)field.Template.FindName("FieldFrame",field);var color=((SolidColorBrush)frame.BorderBrush).Color;int width=(int)Math.Ceiling(field.ActualWidth*scale),height=(int)Math.Ceiling(field.ActualHeight*scale);var bitmap=new RenderTargetBitmap(width,height,96*scale,96*scale,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(field){Stretch=Stretch.Fill},null,new Rect(0,0,field.ActualWidth,field.ActualHeight));bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(root,field.GetType().Name+"-"+scale+".png")))encoder.Save(output);var pixels=new byte[width*height*4];bitmap.CopyPixels(pixels,width*4,0);
                    bool all=true;foreach(var point in new[]{new Point(width/2.0,1.0*scale),new Point(width/2.0,height-1.0*scale),new Point(1.0*scale,height/2.0),new Point(width-1.0*scale,height/2.0)}){bool found=false;int radius=(int)Math.Ceiling(scale);for(int y=Math.Max(0,(int)point.Y-radius);y<Math.Min(height,(int)point.Y+radius+1);y++)for(int x=Math.Max(0,(int)point.X-radius);x<Math.Min(width,(int)point.X+radius+1);x++){int i=(y*width+x)*4;if(pixels[i+3]>128&&Math.Abs(pixels[i]-color.B*pixels[i+3]/255)<40&&Math.Abs(pixels[i+1]-color.G*pixels[i+3]/255)<40&&Math.Abs(pixels[i+2]-color.R*pixels[i+3]/255)<40)found=true;}all&=found;}
                    check(all,field.GetType().Name+" renders all four border edges at "+(scale*100)+" percent; expected="+color+"; border="+frame.BorderThickness+"; size="+field.ActualWidth+"/"+field.ActualHeight);
                }
                var toggle=(ToggleButton)combo.Template.FindName("DropDownToggle",combo);foreach(double x in new[]{combo.ActualWidth/2,combo.ActualWidth-12}){var hit=combo.InputHitTest(new Point(x,combo.ActualHeight/2)) as DependencyObject;DependencyObject node=hit;while(node!=null&&node!=toggle&&node!=combo)node=VisualTreeHelper.GetParent(node);check(node==toggle,"ComboBox hit target reaches the drop-down button at "+x+"; hit="+(hit==null?"null":hit.GetType().FullName)+"; resolved="+(node==null?"null":node.GetType().FullName)+"; toggle="+toggle.ActualWidth+"x"+toggle.ActualHeight);}var peer=new System.Windows.Automation.Peers.ToggleButtonAutomationPeer(toggle);var toggleProvider=peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Toggle);foreach(var contract in toggleProvider.GetType().GetInterfaces())if(contract.FullName=="System.Windows.Automation.Provider.IToggleProvider")contract.GetMethod("Toggle").Invoke(toggleProvider,null);NavigationTests.Wait(Task.Delay(80));check(combo.IsDropDownOpen&&((Popup)combo.Template.FindName("PART_Popup",combo)).IsOpen,"clicking the ComboBox drop-down control opens the selection popup");var popup=(Popup)combo.Template.FindName("PART_Popup",combo);check(Object.ReferenceEquals(popup.PlacementTarget,combo),"drop-down popup is positioned relative to its field");var popupChild=(FrameworkElement)popup.Child;var item=combo.ItemContainerGenerator.ContainerFromIndex(1) as ComboBoxItem;check(popupChild.ActualHeight>20&&item!=null&&item.ActualHeight>10,"open ComboBox renders selectable items in a visible popup; popup="+popupChild.ActualWidth+"x"+popupChild.ActualHeight+" item="+(item==null?"missing":item.ActualHeight.ToString()));combo.SelectedIndex=1;combo.IsDropDownOpen=false;combo.IsEditable=true;combo.Text="Custom font";w.UpdateLayout();var editable=(TextBox)combo.Template.FindName("PART_EditableTextBox",combo);check(editable.Text=="Custom font"&&password.Password=="fixture","editable selection and password content survive the shared field templates");foreach(var test in new[]{Tuple.Create(combo.ActualWidth/2,(DependencyObject)editable),Tuple.Create(combo.ActualWidth-12,(DependencyObject)toggle)}){var node=combo.InputHitTest(new Point(test.Item1,combo.ActualHeight/2)) as DependencyObject;while(node!=null&&node!=test.Item2&&node!=combo)node=VisualTreeHelper.GetParent(node);check(node==test.Item2,"editable ComboBox keeps the text area and drop-down arrow clickable");}
                NextStageTests.Draw(w,Path.Combine(root,"field-borders.png"));
            }finally{w.Close();}
        }
    }
}
#endif